import {accountsEnabled,refreshAccountHeader} from './account-header.js';
export function initCommunity({open,toast,esc,allPlaces}){
const $=s=>document.querySelector(s),key='lavita-community-demo';
const initial=()=>({name:'Sofía',points:1250,saved:[],used:[]});let user=initial(), visibleIds=null;
try{const x=JSON.parse(sessionStorage.getItem(key));if(x&&typeof x.name==='string'&&Number.isFinite(x.points)&&Array.isArray(x.saved)&&Array.isArray(x.used))user=x;}catch{}
const coupons=[
{id:"salsa",value:"GRATIS",title:"Tu primera clase de salsa",subtitle:"Clase muestra · ARIA",label:"PARA NUEVOS ALUMNOS",color:"rose",real:true},
{id:'spa',value:'20%',title:'Tu momento de pausa',subtitle:'Spa Condesa · Masaje y facial',label:'EN TU EXPERIENCIA',color:'rose'},
{id:'hostal',value:'15%',title:'Quédate un poco más',subtitle:'Hostal Roma Condesa',label:'EN UNA NOCHE DE EJEMPLO',color:'cream'},
{id:'andaz',value:'10%',title:'Escápate sin salir del barrio',subtitle:'Andaz Mexico City Condesa',label:'EN UNA ESTANCIA DE EJEMPLO',color:'wine'},
{id:'vinito',value:'15%',title:'Manos al barro',subtitle:'Vinito y torno · Luaa',label:'EN TU EXPERIENCIA',color:'cream'},
{id:'pignoise',value:'2×1',title:'La música se comparte',subtitle:'Pignoise · Foro Indie Rocks!',label:'EN ACCESOS DE EJEMPLO',color:'wine'},
{id:'ceniza',value:'25%',title:'Nos vemos en el cine',subtitle:'Cine Tonalá · Roma Sur',label:'EN TU ENTRADA',color:'rose'},
{id:'cabuya',value:'20%',title:'Una mesa, mil historias',subtitle:'Cabuya · Hipódromo Condesa',label:'EN TU CONSUMO',color:'cream'},
{id:'limantour',value:'15%',title:'Margarita al pastor',subtitle:'Licorería Limantour',label:'EN TU CONSUMO',color:'wine'}];
coupons.unshift(coupons.pop());
const find=id=>coupons.find(c=>c.id===id);
function persist(){try{sessionStorage.setItem(key,JSON.stringify(user));}catch{}update();}
function update(){if(accountsEnabled){refreshAccountHeader();return;}$('#profile-name').textContent=user.name;$('.avatar').textContent=user.name.slice(0,1).toUpperCase();$('#profile-points').textContent=user.points.toLocaleString('es-MX')+' pts · Demo';}
function card(c){const p=allPlaces.find(p=>p.id===c.id);return `<article class="coupon ${c.color}"><button class="coupon-open" data-coupon="${c.id}" aria-label="${esc(c.subtitle)} · ${c.value} · ${c.real?'Publicado por ARIA':'Cupón demo no canjeable'}"><img src="${p.image.src}" alt="${esc(p.name)}" width="160" height="180" loading="lazy"><span class="coupon-content"><span class="coupon-demo">${c.real?'ARIA · Clase muestra':'Demo · No canjeable'}</span><strong class="coupon-value">${c.value}</strong><span class="coupon-venue">${esc(c.subtitle)}</span>${user.saved.includes(c.id)?'<span class="coupon-saved">Guardado ♡</span>':''}</span></button></article>`;}
function selected(){return coupons.filter(c=>!visibleIds||visibleIds.has(c.id));}
function cards(){const list=selected();return list.length?list.map(card).join(''):'<p class="coupon-empty">No hay cupones para esta selección.</p>';}
function updateControls(){const scrollable=track.scrollWidth>track.clientWidth+2;$('#coupon-prev').disabled=!scrollable||track.scrollLeft<=2;$('#coupon-next').disabled=!scrollable||track.scrollLeft+track.clientWidth>=track.scrollWidth-2;}
function refresh(){const track=$('#coupon-track');const left=track.scrollLeft;track.innerHTML=cards();track.scrollLeft=left;$('#coupon-count').textContent='('+selected().length+')';updateControls();document.querySelectorAll('#catalog [data-coupon]').forEach(b=>{b.textContent=find(b.dataset.coupon)?.real?'Ver clase muestra gratis ↗':user.saved.includes(b.dataset.coupon)?'Guardado ♡ · Ver cupón':'Ver cupón de ejemplo ↗';});}
function showCoupon(id){const c=find(id);if(!c)return;const p=allPlaces.find(p=>p.id===id);if(c.real){open(`<p class="eyebrow">OFERTA PUBLICADA POR ARIA</p><h2 id="dialog-title">Tu primera clase de salsa gratis</h2><p>La academia ARIA anuncia una primera clase sin costo para nuevos alumnos. Consulta las condiciones y agenda directamente con la academia.</p><p>${p.location}</p><a class="button primary" href="${p.official}" target="_blank" rel="noopener noreferrer">Consultar clase gratis en ARIA ↗</a><p class="small">Fuente oficial consultada el 6 de noviembre de 2026. Sujeto a disponibilidad y condiciones de ARIA. La Vita no gestiona la reserva ni confirma tu lugar.</p>`);return;}open(`<p class="eyebrow">CUPÓN FICTICIO · SIN VALOR COMERCIAL</p><h2 id="dialog-title">${c.title}</h2><div class="coupon-detail"><strong>${c.value}</strong><p>${c.subtitle}</p><code>DEMO-VITA-${id.toUpperCase()}</code></div><div class="demo-banner">Este descuento es inventado para mostrar la experiencia de La Vita. No fue ofrecido por el establecimiento u organizador y no se puede canjear.</div><p>Condiciones ilustrativas: un uso por perfil demo, sujeto a una futura confirmación del negocio. No incluye una compra, reserva o entrada.</p><div class="actions"><button class="button primary" data-save-coupon="${id}">${user.saved.includes(id)?'Quitar de mis cupones':'Guardar cupón de ejemplo'}</button><button class="button" data-use-coupon="${id}" ${user.used.includes(id)?'disabled':''}>${user.used.includes(id)?'Simulación completada':'Simular uso · +50 puntos'}</button></div><p class="small">El evento o lugar sí existe. Consulta sus condiciones reales por separado.</p><a target="_blank" rel="noopener noreferrer" href="${p.official}">Ver información del organizador ↗</a>`);}
function profile(){open(`<p class="eyebrow">PERFIL DEMO · SIN CUENTA REAL</p><h2 id="dialog-title">Hola, ${esc(user.name)}</h2><div class="profile-summary"><strong>${user.points.toLocaleString('es-MX')} <small>puntos de ejemplo</small></strong><span>Exploradora del barrio</span><progress value="${Math.min(user.points,2000)}" max="2000" aria-label="Puntos ficticios hacia el nivel de 2,000"></progress><p>${Math.max(0,2000-user.points)} puntos para el siguiente nivel de ejemplo.</p></div><form id="profile-form"><label>Nombre de ejemplo<input name="nickname" value="${esc(user.name)}" maxlength="30" required autocomplete="off"></label><button class="button" type="submit">Guardar nombre en esta sesión</button></form><h3>Mis cupones <span class="small">(${user.saved.length})</span></h3><div class="saved-coupons">${user.saved.length?user.saved.map(id=>find(id)).filter(Boolean).map(c=>`<button data-coupon="${c.id}"><strong>${c.value}</strong> ${c.subtitle} ↗</button>`).join(''):'<p>Guarda tu primer cupón desde la cuponera.</p>'}</div><p class="small">Puntos sin valor monetario. Datos guardados únicamente en la sesión de este navegador; no se envían a un servidor.</p><button class="text-button" id="reset-profile">Restablecer perfil y cupones demo</button>`);$('#profile-form').onsubmit=e=>{e.preventDefault();const name=new FormData(e.target).get('nickname').trim();if(!name)return;user.name=name;persist();profile();toast('Nombre de ejemplo actualizado en esta sesión.');};}
$('#profile-button').onclick=profile;
const track=$('#coupon-track');function shift(direction){const first=track.querySelector('.coupon');if(!first)return;track.scrollBy({left:direction*(first.getBoundingClientRect().width+12),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}
track.onscroll=updateControls;
$('#coupon-prev').onclick=()=>shift(-1);$('#coupon-next').onclick=()=>shift(1);track.onkeydown=e=>{if(e.target!==track)return;if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();shift(e.key==='ArrowRight'?1:-1);}};
document.addEventListener('click',e=>{const coupon=e.target.closest('[data-coupon]');if(coupon){showCoupon(coupon.dataset.coupon);return;}const save=e.target.closest('[data-save-coupon]');if(save){const id=save.dataset.saveCoupon;user.saved=user.saved.includes(id)?user.saved.filter(x=>x!==id):[...user.saved,id];persist();refresh();showCoupon(id);toast(user.saved.includes(id)?'Cupón ficticio guardado en tu perfil.':'Cupón retirado de tu perfil.');}const use=e.target.closest('[data-use-coupon]');if(use&&!user.used.includes(use.dataset.useCoupon)){user.used.push(use.dataset.useCoupon);user.points+=50;persist();showCoupon(use.dataset.useCoupon);toast('Simulación completada: +50 puntos de ejemplo. No se realizó ningún canje, compra o reserva.');}if(e.target.closest('#reset-profile')){user=initial();persist();refresh();profile();toast('Perfil de ejemplo restablecido.');}});
update();refresh();return {cards,filter(ids){visibleIds=new Set(ids);refresh();track.scrollLeft=0;updateControls();}};
}
